FROM session_threads
WHERE workspace_uuid = #{workspaceUUID}
  AND parent_thread_uuid IS NOT NULL
  AND external_id IN
  #{externalID}

SELECT external_id FROM session_threads
WHERE workspace_uuid = #{workspaceUUID}
  AND session_external_id = #{sessionExternalID}
  AND parent_thread_uuid IS NULL AND deleted_at IS NULL
ORDER BY created_at ASC, uuid ASC LIMIT 1

