mapper.update:
UPDATE session_threads
SET status = #{status}, stats_initialized = TRUE, usage_initialized = usage_initialized OR #{status} = 'idle', updated_at = NOW()
WHERE workspace_uuid = #{workspaceUUID}
AND session_external_id = #{sessionExternalID}
AND external_id = #{threadExternalID}
AND deleted_at IS NULL

UPDATE session_threads
SET deleted_at = COALESCE(deleted_at, NOW()), updated_at = NOW()
WHERE workspace_uuid = #{workspaceUUID}
AND session_external_id = #{sessionExternalID}
AND deleted_at IS NULL
